module rectangle_matcher #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 16,\n    parameter IDX_WIDTH = 4\n) (\n    input clk, rst_n, start,\n    input [DATA_WIDTH-1:0] tl_r [0:N-1],\n    input [DATA_WIDTH-1:0] tl_c [0:N-1],\n    input [DATA_WIDTH-1:0] br_r [0:N-1],\n    input [DATA_WIDTH-1:0] br_c [0:N-1],\n    output reg [IDX_WIDTH-1:0] match [0:N-1],\n    output reg done,\n    output reg error\n);\n\n// State declarations\nlocalparam [2:0] IDLE   = 3'd0;\nlocalparam [2:0] LOAD   = 3'd1;\nlocalparam [2:0] SORT   = 3'd2;\nlocalparam [2:0] PROCESS = 3'd3;\nlocalparam [2:0] DONE    = 3'd4;\nlocalparam [2:0] ERROR   = 3'd5;\nreg [2:0] state;\n\n// Point structure: {r, c, type, idx}\nlocalparam POINT_WIDTH = 2*DATA_WIDTH + 1 + IDX_WIDTH;\nreg [POINT_WIDTH-1:0] points [0:2*N-1];\n\n// Stack implementation\nreg [IDX_WIDTH-1:0] stack [0:N-1];\nreg [IDX_WIDTH-1:0] sp;\n\n// Counters\nreg [IDX_WIDTH:0] load_count;\nreg [IDX_WIDTH:0] i_count;\nreg [IDX_WIDTH:0] j_count;\nreg [IDX_WIDTH:0] idx_proc;\n\n// Helper macros\n`define POINT_R(p) p[POINT_WIDTH-1 -: DATA_WIDTH]\n`define POINT_C(p) p[POINT_WIDTH-DATA_WIDTH-1 -: DATA_WIDTH]\n`define POINT_TYPE(p) p[POINT_WIDTH-2*DATA_WIDTH-1]\n`define POINT_IDX(p) p[IDX_WIDTH-1:0]\n\n// Comparator for bubble sort\nwire sort_greater;\nassign sort_greater = (`POINT_R(points[j_count]) > `POINT_R(points[j_count+1])) ||\n                     (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) > `POINT_C(points[j_count+1])) ||\n                     (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) == `POINT_C(points[j_count+1]) && `POINT_TYPE(points[j_count]) > `POINT_TYPE(points[j_count+1])) ||\n                     (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) == `POINT_C(points[j_count+1]) && `POINT_TYPE(points[j_count]) == `POINT_TYPE(points[j_count+1]) && `POINT_IDX(points[j_count]) > `POINT_IDX(points[j_count+1]));\n\n// State machine\nalways @(posedge clk or negedge rst_n) begin\n    integer i;  // For-loop index\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        error <= 1'b0;\n        sp <= {IDX_WIDTH{1'b0}};\n        load_count <= {IDX_WIDTH+1{1'b0}};\n        i_count <= {IDX_WIDTH+1{1'b0}};\n        j_count <= {IDX_WIDTH+1{1'b0}};\n        idx_proc <= {IDX_WIDTH+1{1'b0}};\n        \n        // Initialize arrays\n        for (i = 0; i < N; i = i + 1) begin\n            match[i] <= {IDX_WIDTH{1'b0}};\n            stack[i] <= {IDX_WIDTH{1'b0}};\n        end\n        for (i = 0; i < 2*N; i = i + 1) begin\n            points[i] <= {POINT_WIDTH{1'b0}};\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                error <= 1'b0;\n                if (start) begin\n                    state <= LOAD;\n                    load_count <= {IDX_WIDTH+1{1'b0}};\n                end\n            end\n            \n            LOAD: begin\n                if (load_count < 2*N) begin\n                    if (load_count < N) begin\n                        points[load_count] <= {tl_r[load_count], tl_c[load_count], 1'b0, load_count[IDX_WIDTH-1:0]};
                    end else begin\n                        points[load_count] <= {br_r[load_count-N], br_c[load_count-N], 1'b1, (load_count-N)[IDX_WIDTH-1:0]};
                    end\n                    load_count <= load_count + 1'b1;\n                end else begin\n                    state <= SORT;\n                    i_count <= 0;\n                    j_count <= 0;\n                end\n            end\n            \n            SORT: begin\n                if (i_count < 2*N-1) begin\n                    if (j_count < 2*N-1 - i_count) begin\n                        if (sort_greater) begin\n                            points[j_count] <= points[j_count+1];\n                            points[j_count+1] <= points[j_count];\n                        end\n                        j_count <= j_count + 1'b1;\n                    end else begin\n                        j_count <= 0;\n                        i_count <= i_count + 1'b1;\n                    end\n                end else begin\n                    state <= PROCESS;\n                    idx_proc <= 0;\n                    sp <= 0;\n                end\n            end\n            \n            PROCESS: begin\n                if (idx_proc < 2*N) begin\n                    if (`POINT_TYPE(points[idx_proc]) == 1'b0) begin  // TL point\n                        stack[sp] <= `POINT_IDX(points[idx_proc]);\n                        sp <= sp + 1'b1;\n                    end else begin  // BR point\n                        if (sp == 0) begin\n                            error <= 1'b1;\n                            state <= ERROR;\n                        end else begin\n                            sp <= sp - 1'b1;\n                            if (tl_r[stack[sp-1]] >= br_r[`POINT_IDX(points[idx_proc])] ||\n                                tl_c[stack[sp-1]] >= br_c[`POINT_IDX(points[idx_proc])]) begin\n                                error <= 1'b1;\n                                state <= ERROR;\n                            end else begin\n                                match[stack[sp-1]] <= `POINT_IDX(points[idx_proc]) + 1'b1;\n                            end\n                        end\n                    end\n                    idx_proc <= idx_proc + 1'b1;\n                end else begin\n                    if (sp != 0) begin\n                        error <= 1'b1;\n                        state <= ERROR;\n                    end else begin\n                        state <= DONE;\n                        done <= 1'b1;\n                    end\n                end\n            end\n            \n            DONE: begin\n                // Stay in DONE state\n            end\n            \n            ERROR: begin\n                error <= 1'b1;  // Maintain error signal\n            end\n            \n            default: begin\n                state <= IDLE;\n            end\n        endcase\n    end\nend\n\nendmodule\n